
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_tm_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_tm_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.783414671746982e-02, -5.666623493647808e-02, -5.499667548237667e-02, -5.261656493201855e-02, -4.923792239168183e-02, -4.447667625537367e-02, -3.786470176448107e-02, -2.900497674735547e-02, -1.828724478054604e-02, -8.718809352086661e-03, -6.081674147846822e-03, -4.475609488118651e-02, -5.938394558989141e-02, -3.969609070249590e-02, -1.672344028925432e-02, -2.947524269298405e-03, -1.493148448950032e-04, -1.802745636603999e-06, -2.536057097231563e-09, -1.164484830130708e-13]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


